INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'A loom inserts 400 picks per minute and runs at 90% efficiency for a 10-hour shift. Approximately how many picks are actually inserted during that shift?', '["≈ 216,000 picks","≈ 240,000 picks","≈ 400 picks","≈ 4,000 picks"]'::jsonb, '≈ 216,000 picks', 'Picks at 100% efficiency = 400 picks/min × 600 min (10 hr) = 240,000 picks. At 90% efficiency: 240,000 × 0.90 = 216,000 picks.', 2, '{"loom-production-calc"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'A loom inserts 350 picks per minute and runs at 88% efficiency for an 8-hour shift. Approximately how many picks are actually inserted during that shift?', '["≈ 147,840 picks","≈ 168,000 picks","≈ 350 picks","≈ 3,500 picks"]'::jsonb, '≈ 147,840 picks', 'Picks at 100% efficiency = 350 picks/min × 480 min (8 hr) = 168,000 picks. At 88% efficiency: 168,000 × 0.88 = 147,840 picks.', 2, '{"loom-production-calc"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'A fabric has a PPI (picks per inch) of 60. If a loom inserts 216,000 picks in a shift, approximately how many inches of fabric are produced (ignoring take-up effects)?', '["≈ 3,600 inches","≈ 216,000 inches","≈ 60 inches","≈ 12,960,000 inches"]'::jsonb, '≈ 3,600 inches', 'Fabric length (inches) = total picks ÷ PPI = 216,000 ÷ 60 = 3,600 inches.', 2, '{"fabric-length-from-picks"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'A fabric has a PPI of 48. If a loom inserts 147,840 picks in a shift, approximately how many inches of fabric are produced (ignoring take-up effects)?', '["≈ 3,080 inches","≈ 147,840 inches","≈ 48 inches","≈ 7,096,320 inches"]'::jsonb, '≈ 3,080 inches', 'Fabric length (inches) = total picks ÷ PPI = 147,840 ÷ 48 = 3,080 inches.', 2, '{"fabric-length-from-picks"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'A weaving mill''s target is 5,000 meters of fabric per day per loom at 85% efficiency. What is the theoretical (100% efficiency) daily capacity per loom?', '["≈ 5,882 meters","≈ 4,250 meters","≈ 5,000 meters","≈ 5,850 meters"]'::jsonb, '≈ 5,882 meters', 'Theoretical capacity = actual target ÷ efficiency = 5,000 ÷ 0.85 ≈ 5,882 meters.', 2, '{"theoretical-capacity-calc"}'::text[]);
